// Render the social share image (public/og.png, 1200x630): one sentence
// generated by the model, drawn with pressure ribbons on the site's paper
// colour, rasterised by the system Chrome (never qlmanage — see memory).
//
//   npx tsx scripts/og-image.ts [--text 안녕하세요] [--seed 12345] [--out public/og.png]

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import puppeteer from "puppeteer-core";
import {
  bounds,
  normalizedPressure,
  splitStrokes,
  strokeRibbonPath,
  toAbsolute,
} from "../src/lib/strokes";
import { generateDots } from "./generate-node";

const here = path.dirname(fileURLToPath(import.meta.url));
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const argv = process.argv.slice(2);
const arg = (name: string, dflt: string) => {
  const i = argv.indexOf(`--${name}`);
  return i >= 0 && argv[i + 1] ? argv[i + 1] : dflt;
};
const text = arg("text", "한글날 축하합니다!");
const seed = Number(arg("seed", "20261009"));
const out = path.resolve(arg("out", path.join(here, "..", "public", "og.png")));

const { dots } = await generateDots(text, seed, 1.0, 0.8);
const pts = toAbsolute(dots);
const b = bounds(pts);
const strokes = splitStrokes(pts);
const fnorm = normalizedPressure(strokes);
const strokeWidth = Math.max((b.maxY - b.minY) * 0.07, (b.maxX - b.minX) * 0.008);
const PAD = 0.6;
const paths = strokes
  .map((s, i) => `<path d="${strokeRibbonPath(s, fnorm[i], strokeWidth)}" fill="#1a1d24"/>`)
  .join("");
const viewBox = `${b.minX - PAD} ${b.minY - PAD} ${b.maxX - b.minX + 2 * PAD} ${b.maxY - b.minY + 2 * PAD}`;

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  body { margin: 0; width: 1200px; height: 630px; background: #faf8f4;
         font-family: -apple-system, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif;
         color: #1a1d24; position: relative; overflow: hidden; }
  .ink { position: absolute; left: 80px; right: 80px; top: 90px; height: 340px;
         display: flex; align-items: center; justify-content: center; }
  svg { width: 100%; height: 100%; }
  .foot { position: absolute; left: 80px; right: 80px; bottom: 70px;
          display: flex; justify-content: space-between; align-items: baseline; }
  .brand { font-size: 44px; font-weight: 700; letter-spacing: -0.02em; }
  .brand b { color: #2456d6; font-weight: 700; }
  .tag { font-size: 26px; color: #8a8578; }
</style></head><body>
  <div class="ink"><svg viewBox="${viewBox}" preserveAspectRatio="xMidYMid meet">${paths}</svg></div>
  <div class="foot"><div class="brand">hangul<b>.</b>ink</div>
  <div class="tag">A neural network that writes Hangul by hand</div></div>
</body></html>`;

const browser = await puppeteer.launch({ executablePath: CHROME, headless: true });
try {
  const page = await browser.newPage();
  await page.setViewport({ width: 1200, height: 630, deviceScaleFactor: 1 });
  await page.setContent(html, { waitUntil: "load" });
  await page.screenshot({ path: out });
} finally {
  await browser.close();
}
console.log(`"${text}" seed=${seed}: ${dots.length} points, ${strokes.length} strokes -> ${out}`);
process.exit(0);
